import { Effect, Layer } from 'effect'
import {
  RuntimeArtifacts,
  RuntimeError,
  RuntimeState,
  type RuntimeArtifactRef,
  type RuntimeArtifactWrite,
  type RuntimeStateEvent,
} from '@hrbr/runtime-core'
import {
  RuntimeArtifactStoreLive,
  runtimeArtifactExtensionFromContentType,
  type RuntimeArtifactBinaryWrite,
  type RuntimeArtifactBinaryWriter,
  type RuntimeArtifactKind,
  type RuntimeArtifactPointer,
} from '@hrbr/runtime-artifacts'
import {
  RuntimeStatePort,
  flushRuntimeStateWriteQueue,
  type RuntimeStateFlushInfo,
  type RuntimeStateWriteQueue,
  type RuntimeStructuredStateEvent,
} from '@hrbr/runtime-state'
import { TelemetryNoopLive, makeTelemetryLayer, type TelemetryOptions } from '@hrbr/telemetry'

export interface CloudflareRuntimeBindingNames {
  readonly worker: string
  readonly stateDatabase: string
  readonly artifactBucket: string
  readonly cacheNamespace: string
  readonly workflow?: string | undefined
  readonly sessionsObject?: string | undefined
}

export interface CloudflareRuntimeStackSpec {
  readonly name: string
  readonly bindings: CloudflareRuntimeBindingNames
}

export const cloudflareRuntimeStackSpec = (
  spec: CloudflareRuntimeStackSpec
): CloudflareRuntimeStackSpec => spec

export interface CloudflareRuntimeExecutionContext {
  readonly waitUntil?: ((work: Promise<unknown>) => void) | undefined
}

export interface CloudflareRuntimeTelemetryOptions extends TelemetryOptions {}

export interface CloudflareRuntimeR2PutOptions {
  readonly httpMetadata?:
    | {
        readonly contentType?: string | undefined
      }
    | undefined
  readonly customMetadata?: Record<string, string> | undefined
}

export interface CloudflareRuntimeR2Bucket {
  readonly put: (
    key: string,
    value: Uint8Array,
    options?: CloudflareRuntimeR2PutOptions | undefined
  ) => Promise<unknown>
}

export interface CloudflareRuntimeD1Database<TWrite> {
  readonly batch: (writes: readonly TWrite[]) => Promise<unknown>
}

export interface CloudflareRuntimeArtifactWriterOptions {
  readonly bucket: CloudflareRuntimeR2Bucket
  readonly keyPrefix: string
  readonly key?: ((artifact: RuntimeArtifactBinaryWrite) => string) | undefined
  readonly id?: (() => string) | undefined
  readonly publicUrl?: ((key: string) => string) | undefined
}

export interface CloudflareRuntimeStateFlushOptions<TWrite> {
  readonly queue: RuntimeStateWriteQueue<TWrite>
  readonly db: CloudflareRuntimeD1Database<TWrite>
  readonly context?: CloudflareRuntimeExecutionContext | undefined
  readonly now?: (() => number) | undefined
  readonly onEmpty?: (() => void) | undefined
  readonly onSuccess?: ((info: RuntimeStateFlushInfo) => void) | undefined
  readonly onFailure?: ((error: unknown, info: RuntimeStateFlushInfo) => void) | undefined
}

export interface CloudflareRuntimeStateLayerOptions<
  TWrite,
> extends CloudflareRuntimeStateFlushOptions<TWrite> {
  readonly mapEvent: (event: RuntimeStateEvent) => TWrite
}

export interface CloudflareRuntimeStatePortLayerOptions<
  TWrite,
> extends CloudflareRuntimeStateFlushOptions<TWrite> {
  readonly mapEvent: (event: RuntimeStructuredStateEvent) => TWrite
}

let generatedArtifactId = 0

const runtimeArtifactId = (): string => {
  generatedArtifactId += 1
  return Date.now().toString(36) + '-' + String(generatedArtifactId)
}

const trimPathSlashes = (value: string): string => value.replace(/^\/+|\/+$/g, '')

const artifactKey = (
  options: CloudflareRuntimeArtifactWriterOptions,
  artifact: RuntimeArtifactBinaryWrite
): string => {
  const explicitKey = options.key?.(artifact)
  if (explicitKey) return trimPathSlashes(explicitKey)
  const prefix = trimPathSlashes(options.keyPrefix)
  const extension = trimPathSlashes(artifact.extension).replace(/\//g, '-')
  const fileName = (options.id?.() ?? runtimeArtifactId()) + '.' + extension
  return prefix.length > 0 ? prefix + '/' + fileName : fileName
}

const runtimeArtifactKind = (kind: string): RuntimeArtifactKind => {
  if (kind === 'image' || kind === 'output' || kind === 'file') return kind
  return 'file'
}

const runtimeArtifactPointerToRef = (pointer: RuntimeArtifactPointer): RuntimeArtifactRef => ({
  id: pointer.key,
  kind: pointer.kind,
  contentType: pointer.contentType,
  url: pointer.url,
  sizeBytes: pointer.sizeBytes,
  ...(pointer.metadata ? { metadata: pointer.metadata } : {}),
})

const runtimeArtifactWriteToBinaryWrite = (
  artifact: RuntimeArtifactWrite
): RuntimeArtifactBinaryWrite => ({
  kind: runtimeArtifactKind(artifact.kind),
  contentType: artifact.contentType,
  extension: runtimeArtifactExtensionFromContentType(artifact.contentType),
  body: artifact.body,
  ...(artifact.metadata ? { metadata: artifact.metadata } : {}),
})

export function scheduleCloudflareRuntimeWork(
  work: Promise<unknown>,
  context?: CloudflareRuntimeExecutionContext | undefined
): void {
  if (context?.waitUntil) {
    context.waitUntil(work)
    return
  }
  void work
}

export function makeCloudflareRuntimeArtifactWriter(
  options: CloudflareRuntimeArtifactWriterOptions
): RuntimeArtifactBinaryWriter {
  return {
    write: async (artifact) => {
      const key = artifactKey(options, artifact)
      await options.bucket.put(key, artifact.body, {
        httpMetadata: {
          contentType: artifact.contentType,
        },
      })
      return {
        key,
        url: options.publicUrl?.(key) ?? key,
        kind: artifact.kind,
        contentType: artifact.contentType,
        sizeBytes: artifact.body.byteLength,
        ...(artifact.metadata ? { metadata: artifact.metadata } : {}),
      }
    },
  }
}

export const makeCloudflareRuntimeArtifactStoreLayer = (
  options: CloudflareRuntimeArtifactWriterOptions
) => RuntimeArtifactStoreLive(makeCloudflareRuntimeArtifactWriter(options))

export const makeCloudflareRuntimeTelemetryLayer = (
  options: CloudflareRuntimeTelemetryOptions = {}
) => makeTelemetryLayer(options)

export const CloudflareRuntimeTelemetryNoopLive = TelemetryNoopLive

export const makeCloudflareRuntimeArtifactsLayer = (
  options: CloudflareRuntimeArtifactWriterOptions
) => {
  const writer = makeCloudflareRuntimeArtifactWriter(options)
  return Layer.succeed(RuntimeArtifacts, {
    put: (artifact) =>
      Effect.tryPromise({
        try: async () =>
          runtimeArtifactPointerToRef(
            await writer.write(runtimeArtifactWriteToBinaryWrite(artifact))
          ),
        catch: (cause) =>
          new RuntimeError('artifact', 'Cloudflare runtime artifact write failed', {
            kind: artifact.kind,
            contentType: artifact.contentType,
            cause,
          }),
      }),
  })
}

export function flushCloudflareRuntimeStateWrites<TWrite>(
  options: CloudflareRuntimeStateFlushOptions<TWrite>
): void {
  flushRuntimeStateWriteQueue({
    queue: options.queue,
    flush: async (writes) => {
      await options.db.batch(writes)
    },
    now: options.now,
    schedule: (work) => scheduleCloudflareRuntimeWork(work, options.context),
    onEmpty: options.onEmpty,
    onSuccess: options.onSuccess,
    onFailure: options.onFailure,
  })
}

export const makeCloudflareRuntimeStateLayer = <TWrite>(
  options: CloudflareRuntimeStateLayerOptions<TWrite>
) =>
  Layer.succeed(RuntimeState, {
    record: (event) =>
      Effect.sync(() => {
        options.queue.push(options.mapEvent(event))
      }),
    flush: () =>
      Effect.sync(() => {
        flushCloudflareRuntimeStateWrites(options)
      }),
  })

export const makeCloudflareRuntimeStatePortLayer = <TWrite>(
  options: CloudflareRuntimeStatePortLayerOptions<TWrite>
) =>
  Layer.succeed(RuntimeStatePort, {
    record: (event) =>
      Effect.sync(() => {
        options.queue.push(options.mapEvent(event))
      }),
    flush: () =>
      Effect.sync(() => {
        flushCloudflareRuntimeStateWrites(options)
      }),
  })
