import { Cause, Context, Effect, Layer } from 'effect'

export type TelemetryMetadata = Readonly<Record<string, unknown>>
export type TelemetryRedactor = (value: unknown, key?: string | undefined) => unknown

export interface TelemetryEvent {
  readonly name: string
  readonly time?: string | undefined
  readonly attributes?: TelemetryMetadata | undefined
  readonly durationMs?: number | undefined
}

export interface TelemetryWarning {
  readonly code: string
  readonly message: string
  readonly attributes?: TelemetryMetadata | undefined
}

export interface TelemetrySpan {
  readonly name: string
  readonly attributes?: TelemetryMetadata | undefined
}

export interface TelemetrySink {
  readonly event?: ((event: TelemetryEvent) => Effect.Effect<void, unknown>) | undefined
  readonly warning?: ((warning: TelemetryWarning) => Effect.Effect<void, unknown>) | undefined
}

export interface TelemetryOptions {
  readonly sink?: TelemetrySink | undefined
  readonly now?: (() => number) | undefined
  readonly redact?: TelemetryRedactor | undefined
}

export interface Telemetry {
  readonly event: (event: TelemetryEvent) => Effect.Effect<void>
  readonly warning: (warning: TelemetryWarning) => Effect.Effect<void>
  readonly span: <A, E, R>(
    span: TelemetrySpan,
    effect: Effect.Effect<A, E, R>
  ) => Effect.Effect<A, E, R>
  readonly redact: (value: unknown) => unknown
}

export const Telemetry = Context.Service<Telemetry>('@hrbr/Telemetry')

const identityRedactor: TelemetryRedactor = (value) => value

export const redactTelemetryMetadata = (
  metadata: TelemetryMetadata | undefined,
  redact: TelemetryRedactor
): TelemetryMetadata | undefined => {
  if (!metadata) return undefined
  return Object.fromEntries(
    Object.entries(metadata).map(([key, value]) => [key, redact(value, key)])
  )
}

const withTime = (
  event: TelemetryEvent,
  now: () => number,
  redact: TelemetryRedactor
): TelemetryEvent => ({
  ...event,
  time: event.time ?? new Date(now()).toISOString(),
  attributes: redactTelemetryMetadata(event.attributes, redact),
})

const redactWarning = (warning: TelemetryWarning, redact: TelemetryRedactor): TelemetryWarning => ({
  ...warning,
  attributes: redactTelemetryMetadata(warning.attributes, redact),
})

const bestEffort = <A, E, R>(effect: Effect.Effect<A, E, R>): Effect.Effect<void, never, R> =>
  effect.pipe(
    Effect.asVoid,
    Effect.catchCause(() => Effect.void)
  )

export const makeTelemetry = (options: TelemetryOptions = {}): Telemetry => {
  const sink = options.sink
  const now = options.now ?? Date.now
  const redact = options.redact ?? identityRedactor

  const event = (input: TelemetryEvent): Effect.Effect<void> => {
    const prepared = withTime(input, now, redact)
    return bestEffort(sink?.event?.(prepared) ?? Effect.void)
  }

  const warning = (input: TelemetryWarning): Effect.Effect<void> => {
    const prepared = redactWarning(input, redact)
    return bestEffort(sink?.warning?.(prepared) ?? Effect.void)
  }

  const span: Telemetry['span'] = (input, effect) => {
    const startedAt = now()
    const baseAttributes = redactTelemetryMetadata(input.attributes, redact)
    return Effect.gen(function* () {
      yield* bestEffort(
        event({
          name: input.name + '.start',
          attributes: {
            ...(baseAttributes ?? {}),
            phase: 'start',
          },
        })
      )

      return yield* effect.pipe(
        Effect.tap(() =>
          bestEffort(
            event({
              name: input.name + '.finish',
              durationMs: now() - startedAt,
              attributes: {
                ...(baseAttributes ?? {}),
                phase: 'finish',
                outcome: 'success',
              },
            })
          )
        ),
        Effect.catchCause((cause) =>
          Effect.gen(function* () {
            yield* bestEffort(
              event({
                name: input.name + '.finish',
                durationMs: now() - startedAt,
                attributes: {
                  ...(baseAttributes ?? {}),
                  phase: 'finish',
                  outcome: 'failure',
                  cause: Cause.pretty(cause).slice(0, 500),
                },
              })
            )
            return yield* Effect.failCause(cause)
          })
        )
      )
    })
  }

  return {
    event,
    warning,
    span,
    redact,
  }
}

export const makeTelemetryLayer = (options: TelemetryOptions = {}) =>
  Layer.succeed(Telemetry, makeTelemetry(options))

export const TelemetryNoopLive = makeTelemetryLayer()

export type RuntimeTelemetryEvent = TelemetryEvent
export type RuntimeTelemetryWarning = TelemetryWarning
export type RuntimeTelemetrySpan = TelemetrySpan
export type RuntimeTelemetrySink = TelemetrySink
export type RuntimeTelemetryOptions = TelemetryOptions
export type RuntimeTelemetryRedactor = TelemetryRedactor
export type RuntimeTelemetry = Telemetry

export const RuntimeTelemetry = Telemetry
export const makeRuntimeTelemetry = makeTelemetry
export const makeRuntimeTelemetryLayer = makeTelemetryLayer
export const RuntimeTelemetryNoopLive = TelemetryNoopLive
